CREATE SECURITY INTEGRATION my_oauth_int
    TYPE = OAUTH
    OAUTH_CLIENT = CUSTOM
    OAUTH_CLIENT_TYPE = 'CONFIDENTIAL'
    OAUTH_REDIRECT_URI = 'https://example.com/oauth/callback';

CREATE OR REPLACE SECURITY INTEGRATION IF NOT EXISTS my_oauth_int
    TYPE = OAUTH
    OAUTH_CLIENT = CUSTOM
    OAUTH_CLIENT_TYPE = 'PUBLIC'
    OAUTH_REDIRECT_URI = 'https://example.com/oauth/callback'
    ENABLED = TRUE
    OAUTH_ALLOW_NON_TLS_REDIRECT_URI = FALSE
    OAUTH_ENFORCE_PKCE = TRUE
    OAUTH_ENABLE_ROLE_SELECTION = FALSE
    OAUTH_USE_SECONDARY_ROLES = NONE
    PRE_AUTHORIZED_ROLES_LIST = ('my_role_1', 'my_role_2')
    ALLOWED_ROLES_LIST = ('my_analyst_role')
    BLOCKED_ROLES_LIST = ('ACCOUNTADMIN', 'SECURITYADMIN')
    OAUTH_ISSUE_REFRESH_TOKENS = TRUE
    OAUTH_ACCESS_TOKEN_VALIDITY = 600
    OAUTH_REFRESH_TOKEN_VALIDITY = 86400
    NETWORK_POLICY = 'my_network_policy'
    OAUTH_CLIENT_RSA_PUBLIC_KEY = 'MIIBIjANBgkqh...'
    OAUTH_CLIENT_RSA_PUBLIC_KEY_2 = 'MIIBIjANBgkqh...'
    COMMENT = 'custom oauth client';

CREATE SECURITY INTEGRATION my_oauth_int
    TYPE = OAUTH
    OAUTH_CLIENT = CUSTOM
    OAUTH_CLIENT_TYPE = 'CONFIDENTIAL'
    OAUTH_REDIRECT_URI = 'https://example.com/oauth/callback'
    OAUTH_USE_SECONDARY_ROLES = IMPLICIT
    BLOCKED_ROLES_LIST = ();
